#include "stdlib/blas/base/drotg_cblas.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/blas/base/drotg.h"
#include "stdlib/strided/base/min_view_buffer_index.h"

/**
* Constructs a Givens plane rotation.
*
* @param a        first input value
* @param b        second input value
* @param Out      output array
* @param strideOut  output stride length
*/
void API_SUFFIX( c_drotg )( const double a, const double b, double *Out, const CBLAS_INT strideOut ) {
	API_SUFFIX( cblas_drotg )( a, b, Out, strideOut );
}

/**
* Constructs a Givens plane rotation using alternative indexing semantics.
*
* @param a        first input value
* @param b        second input value
* @param Out      output array
* @param strideOut  output stride length
* @param offsetOut  starting index for `Out`
*/
void API_SUFFIX( c_drotg_assign )( const double a, const double b, double *Out, const CBLAS_INT strideOut, const CBLAS_INT offsetOut ) {
	Out += stdlib_strided_min_view_buffer_index( 4, strideOut, offsetOut ); // adjust array pointer
	API_SUFFIX( cblas_drotg )( a, b, Out, strideOut );
}
